mapper.select:
WITH RECURSIVE category_tree AS ( -- 1. 基礎錨點：先找出起點 SELECT id, category_name, parent_id FROM category WHERE category_name = #{categoryName} -- 這裡輸入你想查詢類別名稱
UNION ALL
-- 2. 遞迴成員：拿上一次找到的 id，去對照下一層的 parent_id SELECT c.id, c.category_name, c.parent_id FROM category c INNER JOIN category_tree ct ON c.parent_id = ct.id ) -- 3. 最後把整棵樹的資料倒出來 SELECT * FROM category_tree;
